[
  {
    "description": "Update literature_review.md with a summary of the latest experimental and theoretical breakthroughs in room-temperature superconductivity (2020–2025), including hydride and nickelate systems, with citations.",
    "expectedFiles": ["literature_review.md"],
    "criteria": ["c1"],
    "expectedSymbols": ["Literature Review", "Introduction"]
  },
  {
    "description": "Expand theoretical_framework.md to include a proposed novel mechanism (e.g., exciton-mediated, plasmon-mediated, or topological) that could enable room-temperature superconductivity, with mathematical or conceptual justification, and create docs/novel_mechanism.md with detailed exposition.",
    "expectedFiles": ["theoretical_framework.md", "docs/novel_mechanism.md"],
    "criteria": ["c2"],
    "expectedSymbols": ["Theoretical Framework", "Introduction"]
  },
  {
    "description": "Revise candidate_materials.md to incorporate new candidate compounds (e.g., ternary hydrides, doped nickelates, carbon-based systems) with predicted Tc, synthesis feasibility, and stability notes, and populate data/superconductor_database.json with at least 20 curated entries from literature including Tc, pressure, composition, and reference DOI.",
    "expectedFiles": ["candidate_materials.md", "data/superconductor_database.json"],
    "criteria": ["c3", "c11"],
    "expectedSymbols": ["Candidate Materials", "Hydrides"]
  },
  {
    "description": "Update synthesis_methods.md with detailed protocols for high-pressure synthesis, thin-film deposition, or flux growth for the top candidate materials, including safety and equipment requirements, and create docs/experimental_protocol_hydride.md with a step-by-step protocol for hydride synthesis.",
    "expectedFiles": ["synthesis_methods.md", "docs/experimental_protocol_hydride.md"],
    "criteria": ["c4"],
    "expectedSymbols": ["Synthesis Methods", "High-Pressure"]
  },
  {
    "description": "Enhance characterization_techniques.md with a section on advanced techniques (e.g., muon spin rotation, neutron scattering, scanning SQUID) and how they confirm superconductivity in candidate materials.",
    "expectedFiles": ["characterization_techniques.md"],
    "criteria": ["c5"],
    "expectedSymbols": ["Characterization Techniques", "Resistivity Measurements"]
  }
]

{
  "verdicts": [
    {
      "id": "c1",
      "status": "met",
      "rationale": "literature_review.md includes summaries of hydride (H3S, LaH10) and nickelate systems, with key papers and open questions."
    },
    {
      "id": "c2",
      "status": "unmet",
      "rationale": "theoretical_framework.md does not incorporate the novel plasmon-mediated mechanism detailed in docs/novel_mechanism.md; it needs a section referencing that document.",
      "todos": [
        {
          "description": "Add a section to theoretical_framework.md summarizing the novel plasmon-mediated pairing mechanism and linking to docs/novel_mechanism.md",
          "expectedFiles": ["theoretical_framework.md"]
        }
      ]
    },
    {
      "id": "c3",
      "status": "met",
      "rationale": "candidate_materials.md lists hydrides, cuprates, nickelates, and carbon-based systems with Tc, synthesis notes, and stability information."
    },
    {
      "id": "c4",
      "status": "met",
      "rationale": "synthesis_methods.md contains detailed protocols for high-pressure, thin-film, and flux methods with safety; docs/experimental_protocol_hydride.md provides a specific hydride protocol."
    },
    {
      "id": "c5",
      "status": "met",
      "rationale": "characterization_techniques.md includes a section on advanced techniques (muon spin rotation, neutron scattering) and cross-validation."
    },
    {
      "id": "c6",
      "status": "met",
      "rationale": "roadmap.md has a phased plan covering computational screening, synthesis, characterization, milestones, and risk mitigation; docs/manufacturing_scalability.md provides scalability analysis."
    },
    {
      "id": "c7",
      "status": "met",
      "rationale": "docs/challenges_and_mitigations.md addresses metastability, air sensitivity, cost, and scalability with mitigation strategies."
    },
    {
      "id": "c8",
      "status": "met",
      "rationale": "docs/experimental_feedback_loop.md describes a closed-loop workflow between computational predictions, synthesis, characterization, and theory refinement."
    },
    {
      "id": "c9",
      "status": "met",
      "rationale": "scripts/predict_tc.py includes an empirical model (Matthias rule) with a command-line interface and documentation."
    },
    {
      "id": "c10",
      "status": "unmet",
      "rationale": "scripts/query_database.py lacks filtering by composition and synthesis method, and does not output a summary table.",
      "todos": [
        {
          "description": "Add --composition and --synthesis filters to scripts/query_database.py and output a formatted summary table",
          "expectedFiles": ["scripts/query_database.py"]
        }
      ]
    },
    {
      "id": "c11",
      "status": "unmet",
      "rationale": "data/superconductor_database.json has only 8 entries (needs at least 20) and lacks DOI references.",
      "todos": [
        {
          "description": "Add at least 12 more curated entries to data/superconductor_database.json with Tc, pressure, composition, and DOI",
          "expectedFiles": ["data/superconductor_database.json"]
        }
      ]
    },
    {
      "id": "c12",
      "status": "unmet",
      "rationale": "README.md does not contain a 'How to Contribute' section or a link to docs/experimental_feedback_loop.md.",
      "todos": [
        {
          "description": "Add a 'How to Contribute' section and a link to docs/experimental_feedback_loop.md in README.md",
          "expectedFiles": ["README.md"]
        }
      ]
    }
  ],
  "newCriteria": []
}

