{
  "missionStatement": "Implement a computational screening pipeline and machine learning models to accelerate discovery of room-temperature superconducting compounds, and create tools for experimental design and data analysis.",
  "criteria": [
    {
      "id": "c1",
      "description": "Extend scripts/predict_tc.py to include a machine learning model (e.g., random forest) trained on the curated database (data/superconductor_database.json) with cross-validation, feature importance, and confidence intervals. The script must accept a composition string and output predicted Tc with uncertainty.",
      "expectedFiles": ["scripts/predict_tc.py"]
    },
    {
      "id": "c2",
      "description": "Create a new script scripts/screen_candidates.py that reads a list of candidate compositions (from a text file or stdin), uses the ML model from predict_tc.py to predict Tc, and applies a simple stability heuristic (e.g., presence in database or known structural family). Output a ranked table of candidates with predicted Tc and stability flag.",
      "expectedFiles": ["scripts/screen_candidates.py"]
    },
    {
      "id": "c3",
      "description": "Create a new document docs/computational_screening_pipeline.md that describes an integrated workflow: high-throughput DFT calculations, phonon calculations, ML prediction, and experimental validation. Include references to existing tools (e.g., VASP, Phonopy) and how the scripts in this repo fit in.",
      "expectedFiles": ["docs/computational_screening_pipeline.md"]
    },
    {
      "id": "c4",
      "description": "Create a new document docs/experimental_design.md that provides a protocol for designing experiments to test top candidates from the screening pipeline, including sample preparation, measurement conditions (e.g., pressure, temperature), and data analysis steps (e.g., resistivity fitting, magnetic susceptibility). Link to characterization_techniques.md and synthesis_methods.md.",
      "expectedFiles": ["docs/experimental_design.md"]
    },
    {
      "id": "c5",
      "description": "Create a new script scripts/analyze_resistivity.py that fits resistivity vs temperature data (input as CSV) to extract Tc (onset, midpoint, zero-resistance) and optionally the residual resistivity ratio. Output a summary table and a plot. Include command-line interface and documentation.",
      "expectedFiles": ["scripts/analyze_resistivity.py"]
    },
    {
      "id": "c6",
      "description": "Expand data/superconductor_database.json to at least 50 curated entries, adding fields for synthesis method, stability notes, and a 'source' field (e.g., 'experimental' or 'theoretical'). Ensure all entries have a DOI or arXiv ID.",
      "expectedFiles": ["data/superconductor_database.json"]
    },
    {
      "id": "c7",
      "description": "Create a new document docs/machine_learning_models.md that documents the ML model(s) used in predict_tc.py, including training data, feature engineering, hyperparameters, cross-validation results, and performance metrics (R², MAE). Include a discussion of limitations and future improvements.",
      "expectedFiles": ["docs/machine_learning_models.md"]
    },
    {
      "id": "c8",
      "description": "Create a new script scripts/visualize_database.py that generates at least two plots from the database: (1) Tc vs pressure scatter plot with color-coded material families, and (2) a heatmap of Tc across composition space (e.g., using a simple embedding). Output PNG files and display summary statistics.",
      "expectedFiles": ["scripts/visualize_database.py"]
    },
    {
      "id": "c9",
      "description": "Update README.md to include a 'Tools' section that lists and describes all scripts (predict_tc.py, screen_candidates.py, analyze_resistivity.py, visualize_database.py, query_database.py) with usage examples and links to their documentation.",
      "expectedFiles": ["README.md"]
    }
  ]
}

